```typescript
import { execFile } from "node:child_process";
import { promisify } from "node:util";

const execFileAsync = promisify(execFile);

export interface CheckResult {
  readonly ok: boolean;
  readonly diagnostics: string;
}

export async function verifyTypeScript(cwd: string): Promise<CheckResult> {
  try {
    await execFileAsync("npx", ["tsc", "--noEmit"], { cwd });
    return { ok: true, diagnostics: "0 errors" };
  } catch (error: unknown) {
    const output =
      error instanceof Error && "stdout" in error
        ? String((error as { stdout: unknown }).stdout)
        : String(error);
    return { ok: false, diagnostics: output.slice(0, 2000) };
  }
}
```

3. **Keep prompts scoped:** Pass only the exact file signatures/interfaces (`*.d.ts` or relevant functions) rather than full files—this preserves context window limits and improves reasoning speed on free or local models.

If you share what hardware (CPU/GPU/RAM) and model runtime you use for your studio, I can save it to your notes and tailor the exact toolset for it.
